  "topics": [
    {
      "id": "trn.t01",
      "statements": {
        "f1": "The LIMS application primary host is trn-lims-cobalt.invalid. Accession searches and validation screens use this deployment.",
        "f2": "On 2026-03-12, the LIMS application primary host moved from the previous host to trn-lims-delta.invalid because storage latency was slowing accession searches. Validation screens were unchanged."
      },
      "query": "What is the current primary host for the LIMS application?"
    },
    {
      "id": "trn.t02",
      "statements": {
        "f1": "The HL7 interface engine uses trn-ifx-results-dune as its outbound results queue. The queue buffers validated messages before delivery to downstream recipients.",
        "f2": "On 2026-03-18, the HL7 interface engine switched its outbound results queue to trn-ifx-results-ash after the previous queue developed intermittent delivery lag."
      },
      "query": "Which outbound results queue does the HL7 interface engine currently use?"
    },
    {
      "id": "trn.t03",
      "statements": {
        "f1": "The analyser middleware connector is deployed at version trn-amw-4.2.1. It translates instrument messages before they enter the LIMS.",
        "f2": "On 2026-04-07, the analyser middleware connector moved to version trn-amw-5.1.4 to correct duplicate acknowledgements from two instrument feeds."
      },
      "query": "What version of the analyser middleware connector is deployed now?"
    },
    {
      "id": "trn.t04",
      "statements": {
        "f1": "The specimen barcode printer uses label template trn-bc-label-flint. Its layout leaves a clear margin around the accession barcode for reliable scanning.",
        "f2": "On 2026-04-14, the specimen barcode printer changed to label template trn-bc-label-harbor because the previous layout was crowding the collection-time field."
      },
      "query": "Which label template does the specimen barcode printer currently use?"
    },
    {
      "id": "trn.t05",
      "statements": {
        "f1": "The result release workflow starts its overnight release window at 00:50 UTC. The window covers results that have passed the applicable QC and review gates.",
        "f2": "On 2026-05-02, the result release workflow moved its overnight release window start to 01:05 UTC to allow more time for late analyser acknowledgements."
      },
      "query": "When does the result release workflow's overnight release window currently start?"
    },
    {
      "id": "trn.t06",
      "statements": {
        "f1": "The QC rules engine runs the active rules profile trn-qcr-apricot. It evaluates instrument control results before patient results can proceed to release.",
        "f2": "On 2026-05-11, the QC rules engine activated profile trn-qcr-bracken after a reviewed change to the control-range mappings."
      },
      "query": "What is the QC rules engine's current active rules profile?"
    },
    {
      "id": "trn.t07",
      "statements": {
        "f1": "The instrument order router uses routing configuration trn-rte-cove. It sends accepted orders to the appropriate analyser feed by assay family.",
        "f2": "On 2026-05-19, the instrument order router adopted routing configuration trn-rte-basalt to account for a revised assay-to-feed mapping."
      },
      "query": "Which routing configuration is active for the instrument order router?"
    },
    {
      "id": "trn.t08",
      "statements": {
        "f1": "The FHIR results gateway's endpoint host is trn-fhir-iris.invalid. The gateway serves released observations to approved internal clients.",
        "f2": "On 2026-06-03, the FHIR results gateway changed its endpoint host to trn-fhir-juniper.invalid because the previous host needed network maintenance."
      },
      "query": "What is the current endpoint host for the FHIR results gateway?"
    },
    {
      "id": "trn.t09",
      "statements": {
        "f1": "The accession ingest worker waits 29 seconds before retrying a failed ingest. That pause limits repeated submissions when an upstream feed is unavailable.",
        "f2": "On 2026-06-16, the accession ingest worker's retry delay after a failed ingest changed to 23 seconds following a review of transient feed recovery times."
      },
      "query": "How long does the accession ingest worker currently wait before retrying a failed ingest?"
    },
    {
      "id": "trn.t10",
      "statements": {
        "f1": "The sample image archive stores its objects in bucket trn-arc-ridgeline. Image metadata retains the accession link used for retrieval.",
        "f2": "On 2026-06-24, the sample image archive moved to bucket trn-arc-meadow because the previous bucket's lifecycle configuration could not support the revised image tier."
      },
      "query": "Which storage bucket does the sample image archive currently use?"
    },
    {
      "id": "trn.t11",
      "statements": {
        "f1": "The calibration record store retains records for 31 months. Records remain linked to the instrument and lot that produced each calibration event.",
        "d": "The calibration record store accepts records only after the instrument identifier and calibration outcome have passed schema validation."
      },
      "query": "What is the calibration record store's retention period?"
    },
    {
      "id": "trn.t12",
      "statements": {
        "f1": "The downtime alert service sends notifications to channel trn-alert-prairie. Alerts include the affected system and the start of the interruption.",
        "d": "The downtime alert service groups repeated health-check failures into one incident so responders do not receive a separate notice for every probe."
      },
      "query": "Which notification channel does the downtime alert service use?"
    },
    {
      "id": "trn.t13",
      "statements": {
        "f1": "The LIMS throughput monitor publishes its operations dashboard at trn-dash-summit. It shows accession volume and processing lag by shift.",
        "d": "The LIMS throughput monitor excludes cancelled accessions from its completed-work count, while retaining them in the intake total."
      },
      "query": "What is the LIMS throughput monitor's operations dashboard?"
    },
    {
      "id": "trn.t14",
      "statements": {
        "f1": "The LIMS audit exporter sends events to destination queue trn-aud-moraine. The exporter includes the actor and accession reference in each event.",
        "f2": "On 2026-07-08, the LIMS audit exporter changed its destination queue to trn-aud-thistle while the previous queue underwent broker maintenance.",
        "f3": "The LIMS audit exporter's destination queue is back to trn-aud-moraine after broker maintenance finished and delivery checks passed."
      },
      "query": "What is the LIMS audit exporter's current destination queue?"
    },
    {
      "id": "trn.t15",
      "statements": {
        "f1": "The result delivery batch dispatches daily at 03:10 UTC. It packages released reports for recipients that use scheduled delivery.",
        "f2": "On 2026-07-15, the result delivery batch's daily dispatch time changed to 04:10 UTC to avoid overlap with a recipient's maintenance window.",
        "f3": "The result delivery batch is back to a daily dispatch time of 03:10 UTC because the recipient's maintenance window no longer overlaps delivery."
      },
      "query": "At what time does the result delivery batch currently dispatch each day?"
    },
    {
      "id": "trn.t16",
      "statements": {
        "f1": "The ward sample scan service uses trn-scan-banyan.invalid as its intake host. It records scan events before specimens enter accessioning.",
        "f2": "On 2026-07-22, the ward sample scan service changed its intake host to trn-scan-aster.invalid while the previous host's certificate chain was repaired.",
        "f3": "The ward sample scan service's intake host is back to trn-scan-banyan.invalid after the certificate repair passed client connectivity checks."
      },
      "query": "What is the ward sample scan service's current intake host?"
    }
  ],
